// ─── File: demo/RebalanceDemo.java ───
// This file contains multiple top-level classes for the runnable demo.
// In a real project each would live in its own file.
package com.bank.settlement.demo;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RebalanceDemo {

    private static final Logger log = Logger.getLogger(RebalanceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        int partitions = 12;

        log.info("=== Strategy 1: EAGER (stop-the-world on every change) ===");
        GroupCoordinator eager = new GroupCoordinator(partitions, new EagerStrategy());
        runRollingDeploy(eager, 6);
        log.info(() -> "EAGER total stop-the-world rebalances = " + eager.getStopTheWorldCount()
                + ", partitions moved = " + eager.getPartitionsMoved());

        log.info("=== Strategy 2: COOPERATIVE + STATIC MEMBERSHIP ===");
        GroupCoordinator coop = new GroupCoordinator(partitions, new CooperativeStaticStrategy());
        runRollingDeploy(coop, 6);
        log.info(() -> "COOP total stop-the-world rebalances = " + coop.getStopTheWorldCount()
                + ", partitions moved = " + coop.getPartitionsMoved());
    }

    // Simulate a Kubernetes rolling deploy: each pod stops then quickly restarts.
    private static void runRollingDeploy(GroupCoordinator coordinator, int pods) {
        for (int i = 0; i < pods; i++) {
            coordinator.join(new ConsumerMember("settlement-consumer-" + i));
        }
        coordinator.assign(); // initial assignment
        for (int i = 0; i < pods; i++) {
            String instanceId = "settlement-consumer-" + i;
            coordinator.leave(instanceId, true);           // pod terminates (quick restart)
            coordinator.join(new ConsumerMember(instanceId)); // same pod comes back fast
        }
    }
}

// ─── Would be in GroupCoordinator.java in a real project ───
class GroupCoordinator {
    private final int partitions;
    private final RebalanceStrategy strategy;
    private final List<ConsumerMember> members = new ArrayList<>();
    private int stopTheWorldCount = 0;
    private int partitionsMoved = 0;
    private static final Logger log = Logger.getLogger(GroupCoordinator.class.getName());

    GroupCoordinator(int partitions, RebalanceStrategy strategy) {
        this.partitions = partitions;
        this.strategy = strategy;
    }

    void join(ConsumerMember m) {
        members.add(m);
        RebalanceOutcome out = strategy.onMembershipChange(members.size(), partitions, true, m.isQuickRestart());
        apply(out, "JOIN " + m.getInstanceId());
    }

    void leave(String instanceId, boolean quickRestart) {
        members.removeIf(x -> x.getInstanceId().equals(instanceId));
        ConsumerMember ghost = new ConsumerMember(instanceId);
        ghost.setQuickRestart(quickRestart);
        RebalanceOutcome out = strategy.onMembershipChange(members.size(), partitions, false, quickRestart);
        apply(out, "LEAVE " + instanceId);
    }

    void assign() {
        RebalanceOutcome out = strategy.onMembershipChange(members.size(), partitions, true, false);
        apply(out, "INITIAL ASSIGN");
    }

    private void apply(RebalanceOutcome out, String reason) {
        if (out.stopTheWorld()) stopTheWorldCount++;
        partitionsMoved += out.partitionsMoved();
        log.fine(() -> reason + " -> stopTheWorld=" + out.stopTheWorld() + " moved=" + out.partitionsMoved());
    }

    int getStopTheWorldCount() { return stopTheWorldCount; }
    int getPartitionsMoved() { return partitionsMoved; }
}

// ─── Would be in ConsumerMember.java in a real project ───
class ConsumerMember {
    private final String instanceId; // stable identity = group.instance.id
    private boolean quickRestart = true;

    ConsumerMember(String instanceId) { this.instanceId = instanceId; }
    String getInstanceId() { return instanceId; }
    boolean isQuickRestart() { return quickRestart; }
    void setQuickRestart(boolean v) { this.quickRestart = v; }
}

// ─── Would be in RebalanceStrategy.java in a real project ───
interface RebalanceStrategy {
    RebalanceOutcome onMembershipChange(int liveMembers, int partitions, boolean isJoin, boolean quickRestart);
}

// ─── Would be in RebalanceOutcome.java in a real project ───
record RebalanceOutcome(boolean stopTheWorld, int partitionsMoved) {}

// ─── Would be in EagerStrategy.java in a real project ───
class EagerStrategy implements RebalanceStrategy {
    public RebalanceOutcome onMembershipChange(int liveMembers, int partitions, boolean isJoin, boolean quickRestart) {
        // Eager: ANY change revokes ALL partitions from EVERYONE.
        return new RebalanceOutcome(true, partitions);
    }
}

// ─── Would be in CooperativeStaticStrategy.java in a real project ───
class CooperativeStaticStrategy implements RebalanceStrategy {
    public RebalanceOutcome onMembershipChange(int liveMembers, int partitions, boolean isJoin, boolean quickRestart) {
        // Static membership: a quick restart of the SAME instance id => no rebalance.
        if (quickRestart) return new RebalanceOutcome(false, 0);
        if (liveMembers == 0) return new RebalanceOutcome(false, 0);
        // Cooperative: only move the few partitions that must move to the new owner.
        int moved = Math.max(1, partitions / Math.max(1, liveMembers));
        return new RebalanceOutcome(false, moved); // surviving members keep running
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
